            logging.info("---------Stop processing emails---------")
            return
    companys = defaultdict(list)
    key = ['company', 'state', 'next_step', 'subject', 'sender_name', 'sender_mail', 'recipient_name', 'recipient_mail', 'date', 'body', 'length', 'rank']
